import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const ReservationForm = () => {
  const [formData, setFormData] = useState({
    dateRetrait: '',
    heureRetrait: '10:00',
    dateRetour: '',
    heureRetour: '10:00',
    transmission: 'Manuelle',
    siege: '4',
    categorie: 'Berline',
    carburant: 'Diesel'
  });

  const [results, setResults] = useState([]);
  const [isSearching, setIsSearching] = useState(false);
  const navigate = useNavigate();

  const mockCars = [
    { id: 1, modele: 'Peugeot 208', categorie: 'Compacte', prix: 120 },
    { id: 2, modele: 'Renault Clio', categorie: 'Compacte', prix: 110 },
    { id: 3, modele: 'VW Golf', categorie: 'Berline', prix: 150 },
    { id: 4, modele: 'Toyota RAV4', categorie: 'SUV', prix: 180 }
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSearching(true);
    
    setTimeout(() => {
      const filteredCars = mockCars.filter(car => {
        return (
          car.categorie === formData.categorie
        );
      });
      
      setResults(filteredCars);
      setIsSearching(false);
      document.getElementById('results').scrollIntoView({ behavior: 'smooth' });
    }, 300);
  };

  useEffect(() => {
    const today = new Date().toISOString().split('T')[0];
    const defaultReturnDate = new Date();
    defaultReturnDate.setDate(defaultReturnDate.getDate() + 2);
    const defaultReturnDateStr = defaultReturnDate.toISOString().split('T')[0];
    
    setFormData(prev => ({
      ...prev,
      dateRetrait: today,
      dateRetour: defaultReturnDateStr
    }));
  }, []);

  return (
    <div className="max-w-4xl mx-auto p-2 bg-white rounded-lg">
      <div className="flex flex-col md:flex-row gap-2">
        {/* Formulaire compact */}
        <div className="bg-gray-50 p-2 rounded-lg flex-1">
          <h2 className="text-sm font-bold mb-1">Dates de location</h2>
          <div className="grid grid-cols-2 gap-1 mb-2">
            <div>
              <label className="block text-xs mb-0.5">Début*</label>
              <input
                type="date"
                name="dateRetrait"
                value={formData.dateRetrait}
                onChange={handleChange}
                className="w-full p-1 text-xs border rounded"
                required
              />
            </div>
            <div>
              <label className="block text-xs mb-0.5">Heure*</label>
              <input
                type="time"
                name="heureRetrait"
                value={formData.heureRetrait}
                onChange={handleChange}
                className="w-full p-1 text-xs border rounded"
                required
              />
            </div>
            <div>
              <label className="block text-xs mb-0.5">Fin*</label>
              <input
                type="date"
                name="dateRetour"
                value={formData.dateRetour}
                onChange={handleChange}
                className="w-full p-1 text-xs border rounded"
                required
              />
            </div>
            <div>
              <label className="block text-xs mb-0.5">Heure*</label>
              <input
                type="time"
                name="heureRetour"
                value={formData.heureRetour}
                onChange={handleChange}
                className="w-full p-1 text-xs border rounded"
                required
              />
            </div>
          </div>

          <h2 className="text-sm font-bold mb-1">Préférences</h2>
          <div className="grid grid-cols-2 gap-1">
            <div>
              <label className="block text-xs mb-0.5">Catégorie</label>
              <select
                name="categorie"
                value={formData.categorie}
                onChange={handleChange}
                className="w-full p-1 text-xs border rounded"
              >
                <option value="Economique">Eco</option>
                <option value="Compacte">Compacte</option>
                <option value="Berline">Berline</option>
                <option value="SUV">SUV</option>
              </select>
            </div>
            <div>
              <label className="block text-xs mb-0.5">Sièges</label>
              <select
                name="siege"
                value={formData.siege}
                onChange={handleChange}
                className="w-full p-1 text-xs border rounded"
              >
                {[2, 4, 5, 7].map(num => (
                  <option key={num} value={num}>{num}</option>
                ))}
              </select>
            </div>
          </div>

          <button
            onClick={handleSubmit}
            className="w-full mt-2 p-1 bg-blue-600 text-white text-xs rounded hover:bg-blue-700"
          >
            {isSearching ? '...' : 'Rechercher'}
          </button>
        </div>

        {/* Résultats */}
        <div id="results" className="flex-1 bg-gray-50 p-2 rounded-lg">
          {isSearching ? (
            <div className="flex justify-center items-center h-full">
              <div className="animate-spin rounded-full h-4 w-4 border-t-2 border-b-2 border-blue-500"></div>
            </div>
          ) : results.length > 0 ? (
            <div>
              <h2 className="text-sm font-bold mb-1">Résultats ({results.length})</h2>
              <div className="overflow-y-auto max-h-60">
                {results.map(car => (
                  <div key={car.id} className="flex justify-between items-center p-1 border-b text-xs">
                    <div>
                      <div className="font-medium">{car.modele}</div>
                      <div className="text-gray-500">{car.categorie}</div>
                    </div>
                    <div className="text-right">
                      <div className="font-bold">{car.prix} €/j</div>
                      <button 
                        onClick={() => navigate('/confirmation')}
                        className="bg-green-500 text-white px-2 py-0.5 rounded text-xs"
                      >
                        Réserver
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ) : (
            <div className="text-center text-gray-500 text-xs py-4">
              Aucun véhicule trouvé
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ReservationForm;
